    faint:   () => tone('sine', 720, 240, 0.08, 0.04),
    bossDown() { hiss(0.7, 0.18, 'lowpass', 1500, 100); arp('triangle', [262, 330, 392, 523], 0.09, 0.4, 0.08); },
