/* js/ui/gacha-ui.js */
/* ============ gacha-ui.js — banners por generación y animación de tirada ============
 * La lógica (probabilidades, pity, shiny, repetidos) está en systems/gacha.js.
 */
G.GachaUI = (() => {
  const $ = G.UI.$;
  let busy = false;
  let gen = 1;

  function init() {
    $('pull-1').onclick = () => pull(1);
    $('pull-10').onclick = () => pull(10, 't1');
    $('pull-10b').onclick = () => pull(10, 't10');
    $('pull-close').onclick = close;

    const tabs = $('gacha-gens');
    G.Gacha.BANNERS.forEach(b => {
      const t = document.createElement('button');
      t.className = 'gen-tab';
      t.dataset.gen = b.gen;
      t.innerHTML = `<b>${b.name}</b><small>Gen ${b.gen}</small>`;
      t.onclick = () => { gen = b.gen; refresh(); };
      tabs.appendChild(t);
    });
  }

  function open() {
    G.UI.show('scr-gacha', true);
    refresh();
  }

  function refresh() {
    const s = G.DB.save;
    const banner = G.Gacha.BANNERS[gen - 1];
    document.querySelectorAll('#gacha-gens .gen-tab').forEach(t => t.classList.toggle('on', +t.dataset.gen === gen));

    const all = G.DEX.filter(p => p.gen === gen);
    const owned = all.filter(p => s.owned[p.dex]).length;
    const shinies = all.filter(p => s.shiny && s.shiny[p.dex]).length;
    const [c1, c2, c3] = banner.color;
    $('banner').style.background =
      `radial-gradient(circle at 80% 30%, rgba(255,210,63,.3), transparent 45%),
       radial-gradient(circle at 15% 80%, rgba(196,123,255,.3), transparent 50%),
       linear-gradient(135deg, ${c1}, ${c2} 55%, ${c3})`;
    $('banner-title').textContent = banner.name + ' Misterioso';
    $('banner-desc').textContent = `Los ${all.length} Pokémon de la generación ${gen}. ¡Los legendarios esperan!`;
    $('gacha-owned').innerHTML = `Tienes ${owned} de ${all.length}` +
      (shinies ? ` · ${G.Icons.html('shiny', 12)} ${shinies} shiny` : '');

    const feat = $('gacha-feat');
    feat.innerHTML = '';
    for (const dex of G.Gacha.featured(gen)) {
      feat.appendChild(G.UI.spriteCanvas(dex, 170, 190, { lively: true, scale: 2, dir: 1 }));
    }

    const pity = (s.pity && s.pity[gen]) || 0;
    $('gacha-pity').textContent = `Tiradas sin legendaria en ${banner.name}: ${pity} / ${G.Gacha.PITY_5}`;

    $('gacha-rates').innerHTML = '<h3>Probabilidades</h3>' + G.Gacha.RATES.slice().reverse().map(([r, w]) => `
      <div><span style="color:${G.Gacha.RARITY_COLOR[r]}">${G.UI.stars(r, 10)} ${G.Gacha.RARITY_NAME[r]}</span>
      <span>${w}% · ${G.Gacha.pool(r, gen).length}</span></div>`).join('') +
      `<div><span>${G.Icons.html('shiny', 12)} Shiny</span><span>1%</span></div>
       <p class="note">· La tirada ×10 garantiza al menos una Épica.<br>
       · A las ${G.Gacha.PITY_5} tiradas sin Legendaria en un banner, la siguiente lo es.<br>
       · 重複夥伴保留金幣回饋；史詩／傳說另升共鳴 +1，最高 +5。<br>
       · 每次重複史詩／傳說另得 1／3 精華；已滿階改得 3／9。普通與異色共用升階。<br>
       · 首次異色仍會解鎖；若已擁有同種普通版本，同時獲得共鳴回饋。<br>
       · Los tickets se consiguen jugando: algunos Pokémon los sueltan al caer, y
         los jefes y los legendarios de las grietas dan tickets ×10.</p>` + G.ResonanceUI.workshop();
    G.ResonanceUI.bindWorkshop(refresh);

    const t = s.tickets;
    $('cost-1').innerHTML = `${G.Icons.html('ticket', 18)} 1`;
    $('cost-10').innerHTML = `${G.Icons.html('ticket', 18)} 10`;
    $('cost-10b').innerHTML = `${G.Icons.html('ticket10', 18)} 1`;
    $('gacha-tickets').innerHTML = `Tienes ${G.Icons.html('ticket', 18)} <b>${t.t1}</b> tickets y ${G.Icons.html('ticket10', 18)} <b>${t.t10}</b> tickets ×10`;
    $('pull-1').disabled = !G.Gacha.costOf(s, 1);
    $('pull-10').disabled = !G.Gacha.costOf(s, 10, 't1');
    $('pull-10b').disabled = !G.Gacha.costOf(s, 10, 't10');
    G.UI.refreshCoins();
  }

  const wait = ms => new Promise(r => setTimeout(r, ms));

  async function pull(n, use = 't1') {
    if (busy) return;
    const res = G.Gacha.pull(G.DB.save, n, gen, use);
    if (!res) { G.Audio.sfx('error'); G.UI.toast('No tienes tickets suficientes: consíguelos jugando'); return; }
    G.Progress.checkAch();
    G.DB.commit(true);
    busy = true;

    const best = Math.max(...res.map(r => r.rarity));
    const fx = $('pull-fx'), slot = $('slot'), out = $('pull-results');
    out.innerHTML = '';
    $('pull-close').classList.add('hidden');
    slot.style.display = '';
    fx.classList.remove('hidden');

    // La tragaperras (ui/slots.js) y luego las cartas.
    await G.Slots.play(slot, res);
    G.Audio.sfx('burst', { rarity: best });
    slot.style.display = 'none';

    for (const r of res) {
      const mon = G.DEX_BY[r.dex];
      const c = document.createElement('div');
      c.className = 'pcard r' + r.rarity + (r.shiny ? ' shiny' : '');
      c.style.setProperty('--rc', r.shiny ? '#9ae6ff' : G.Gacha.RARITY_COLOR[r.rarity]);
      c.innerHTML = `<div class="stars">${G.UI.stars(r.rarity, 24)}</div>`;
      c.appendChild(G.UI.spriteCanvas(r.dex, 132, 120, { lively: r.rarity >= 4 || r.shiny, scale: 2, shiny: r.shiny }));
      const tag = r.isNew
        ? `<span class="new">${r.shiny ? '¡SHINY NUEVO!' : '¡NUEVO!'}</span>`
        : `Repetido · <span class="coin"></span> +${r.refund}`;
      c.insertAdjacentHTML('beforeend', `<b>${r.shiny ? G.Icons.html('shiny', 12) + ' ' : ''}${mon.name}</b><div class="tag">${tag}</div>${G.ResonanceUI.reward(r)}`);
      out.appendChild(c);
      G.Audio.sfx('reveal', { rarity: r.rarity });
      await wait(n === 10 ? 150 : 0);
    }
    $('pull-close').classList.remove('hidden');
    busy = false;
  }

  function close() {
    $('pull-fx').classList.add('hidden');
    refresh();
  }

  return { init, open, get open_() { return !$('pull-fx').classList.contains('hidden'); } };
})();

;
/* js/ui/resonance-ui.js */
/* Visible progression and a deterministic alternative to waiting for one dupe. */
G.ResonanceUI = (() => {
  let selected = 0;
  const R = () => G.Resonance;
  function badge(dex) {
    const n = R().rank(G.DB.save, dex);
    return n ? ` <span class="resonance-badge" title="共鳴升階 +${n}">+${n}</span>` : '';
  }
  function detail(dex) {
    if (!R().eligible(dex)) return '';
    const s = G.DB.save, n = R().rank(s, dex), o = R().offer(s, dex);
    return `<div class="resonance-detail"><strong>共鳴 +${n} / +${R().MAX}</strong><p>${R().summary(s,dex)}</p><small>普通／異色共用；加成用於你操作這隻寶可夢時。${n < 3 ? '+3 解鎖冷卻縮短 5%。' : n < 5 ? '+5 解鎖移速 +5%。' : '已滿階，再次重複可獲得更多精華。'}</small>${o ? `<button type="button" class="btn small resonance-grow" data-grow="${dex}" ${o.affordable ? '' : 'disabled'}>培養至 +${o.next} · ${o.cost} 精華</button>` : ''}<small>持有共鳴精華：${s.resonance?.essence || 0}</small></div>`;
  }
  function bindDetail(box, refresh) {
    const button = box.querySelector('[data-grow]');
    if (button) button.onclick = () => {
      const result = R().exchange(G.DB.save, Number(button.dataset.grow));
      if (!result) return;
      G.DB.commit(true); G.Audio.sfx('legend'); refresh();
    };
  }
  function workshop() {
    const s = G.DB.save;
    const pool = G.DEX.filter(p => R().offer(s, p.dex));
    if (!pool.some(p => p.dex === selected)) selected = pool.find(p => p.dex === s.partner)?.dex || pool[0]?.dex || 0;
    return `<details class="resonance-workshop"><summary>共鳴工坊 · 精華 ${s.resonance?.essence || 0}</summary><p>重複史詩、傳說都能累積精華。你可以指定培養，也可以存起來招募尚未擁有的夥伴。</p><label for="resonance-target">選擇目標（所有世代）</label><select id="resonance-target">${pool.map(p => {
      const o = R().offer(s,p.dex);
      return `<option value="${p.dex}" ${selected === p.dex ? 'selected' : ''}>${p.rarity === 5 ? '傳說' : '史詩'} · ${p.name} · ${o.kind === 'grow' ? '培養 +' + o.next : '首次招募'} · ${o.cost} 精華</option>`;
    }).join('')}</select><p id="resonance-preview" aria-live="polite"></p><button type="button" class="btn gold" id="resonance-exchange">指定培養／招募</button><small>培養：史詩 12／傳說 36；首次招募：史詩 40／傳說 120。招募得到普通版本，從 +0 開始。兌換不消耗招募券、不影響保底。</small></details>`;
  }
  function bindWorkshop(refresh) {
    const select = document.getElementById('resonance-target'), button = document.getElementById('resonance-exchange');
    if (!select || !button) return;
    const update = () => {
      selected = Number(select.value);
      const s = G.DB.save, o = R().offer(s,selected);
      document.getElementById('resonance-preview').textContent = !o ? '所有史詩與傳說都已滿階！精華會繼續保留。' : `${G.DEX_BY[selected].name} · ${o.kind === 'grow' ? '共鳴 +' + R().rank(s,selected) + ' → +' + o.next : '加入收藏（普通版本）'}${o.affordable ? '' : ` · 還差 ${o.cost - (s.resonance?.essence || 0)} 精華`}`;
      button.disabled = !o?.affordable;
      button.textContent = o ? `${o.kind === 'grow' ? '培養至 +' + o.next : '招募 ' + G.DEX_BY[selected].name} · ${o.cost} 精華` : '已全部滿階';
    };
    select.onchange = update; update();
    button.onclick = () => {
      // Re-read cost/rank at click time, then commit before refreshing the UI.
      const result = R().exchange(G.DB.save,selected);
      if (!result) { update(); return; }
      G.Progress.checkAch(); G.DB.commit(true); G.Audio.sfx('legend');
      G.UI.toast(`${G.DEX_BY[selected].name}${result.kind === 'grow' ? ' 共鳴 +' + result.next : ' 已加入收藏'}`);
      refresh(); document.querySelector('.resonance-workshop').open = true;
    };
  }
  function reward(r) {
    if (!r.resonance) return '';
    const a = r.resonance;
    const milestone = a.after !== a.before && a.after === 3 ? '冷卻 −5% 解鎖' : a.after !== a.before && a.after === 5 ? '移速 +5% 解鎖' : '';
    return `<div class="resonance-reward"><strong>${a.capped ? '共鳴 +5 · 滿階回饋' : `共鳴 +${a.before} → +${a.after}`}</strong>${a.capped ? '' : '<span>攻擊 +4% · 生命 +3%</span>'}${milestone ? `<span>${milestone}</span>` : ''}<span>共鳴精華 +${a.essence}</span></div>`;
  }
  return { badge, detail, bindDetail, workshop, bindWorkshop, reward };
})();

