        const dir = ['右方', '右下方', '下方', '左下方', '左方', '左上方', '上方', '右上方'][(Math.round(a / (Math.PI / 4)) + 8) % 8];
        text = s.chest.open > 0 ? `開啟中 ${s.chest.open.toFixed(1)} / 3 秒` : `守護寶箱在${dir} · 靠近停留 3 秒`;
